// Rendering of conditions and actions from the embedded table (see src/bible/generate.js):
// templates with placeholders filled from the event's parameters. Any placeholder that cannot be
// rendered safely keeps Nebula's English line.
// - built-in objects: French only (in English, Nebula's text is kept);
// - extensions, in both languages: the catalog's template replaces Nebula's raw "Event ID n".
//   In French, an extension without French label shows its English template, as the editor does.
static class Tr
{
    // Built-in: (EN template, FR template) variants; extensions: FR / EN templates, expression names
    static readonly Dictionary<string, List<(string en, string fr)>> Builtin = new();
    static readonly Dictionary<string, string> Ext = new();
    static readonly Dictionary<string, string> ExtEn = new();
    static readonly Dictionary<string, (string name, int count)> ExtExpr = new();
    // Parameter codes of compared values: 23 = number comparison, 46 = string comparison
    static readonly int[] ComparisonCodes = { 23, 46 };
    // Headers that Nebula puts in front of actions of system objects
    static readonly Dictionary<string, string> Headers = new()
    {
        ["Special : "] = "Spécial : ", ["Sound : "] = "Son : ", ["New Objects : "] = "Nouveaux objets : ",
        ["storyboard controls : "] = "Contrôles du storyboard : ", ["the timer : "] = "Chronomètre : ",
        ["The mouse pointer and keyboard : "] = "Souris et clavier : ",
    };

    // Loads the table. Only the entries that can be looked up are kept: French ones in French, and the
    // extensions of this project (keys "ext|<.mfx file in lower case>|..."; see Out.ExtFile)
    public static void Load(IEnumerable<string> extFiles)
    {
        using var s = Assembly.GetExecutingAssembly().GetManifestResourceStream("lang.fr.json");
        if (s == null)
            return;
        var files = new HashSet<string>(extFiles.Where(f => f != null).Select(f => f.ToLowerInvariant()));
        bool Used(string key)
        {
            int a = key.IndexOf('|'), b = a < 0 ? -1 : key.IndexOf('|', a + 1);
            return b > a && files.Contains(key.Substring(a + 1, b - a - 1));
        }
        bool fr = L.Lang == "fr";
        using var doc = JsonDocument.Parse(s);
        if (fr)
        {
            foreach (var p in doc.RootElement.GetProperty("builtin").EnumerateObject())
                Builtin[p.Name] = p.Value.EnumerateArray().Select(pair => (pair[0].GetString(), pair[1].GetString())).ToList();
            foreach (var p in doc.RootElement.GetProperty("ext").EnumerateObject())
                if (Used(p.Name)) Ext[p.Name] = p.Value.GetString();
        }
        if (files.Count == 0)
            return;
        if (doc.RootElement.TryGetProperty("extEn", out var extEn))
            foreach (var p in extEn.EnumerateObject())
                if (Used(p.Name)) ExtEn[p.Name] = p.Value.GetString();
        if (doc.RootElement.TryGetProperty("extExpr", out var extExpr))
            foreach (var p in extExpr.EnumerateObject())
                if (Used(p.Name)) ExtExpr[p.Name] = (p.Value[0].GetString(), p.Value[1].GetInt32());
    }

    // Editor name and parameter count of an extension expression (resolver given to Nebula)
    public static (string Name, int ParameterCount)? ExtensionExpression(ParameterExpression e)
    {
        string file = Out.ExtFile(e.ObjectType);
        return file != null && ExtExpr.TryGetValue($"ext|{file.ToLowerInvariant()}|{e.Num}", out var x) ? (x.name, x.count) : null;
    }

    public static string Condition(Condition c, string en) => Translate(c, "C", en, "", "");

    public static string Action(FAction a, string en)
    {
        // Nebula writes "<object or system header> : <text>" for actions: keep the object name,
        // translate the system headers
        string head = "", prefix = "";
        string objName = null;
        try { objName = a.ObjectType >= 0 ? a.GetObjectName() : null; } catch { }
        int sep = en.IndexOf(" : ", StringComparison.Ordinal);
        if (objName != null && en.StartsWith(objName + " : ", StringComparison.Ordinal))
            head = prefix = objName + " : ";
        else if (sep >= 0)
        {
            head = en[..(sep + 3)];
            var player = Rx.Player.Match(head);
            prefix = player.Success ? $"Joueur {player.Groups[1].Value} : "
                   : Headers.TryGetValue(head, out var frHead) ? frHead : head;
        }
        return Translate(a, "A", en, head, prefix);
    }

    // enHead: header of Nebula's action text ("Obj : ", "Sound : "...), prefix: its French version
    static string Translate(ACEventBase x, string kind, string en, string enHead, string prefix)
    {
        bool negated = x is Condition c && c.OtherFlags["Negated"];
        // Nebula's text without the header / "NOT ", to match the EN templates against
        string body = en[enHead.Length..];
        if (negated && body.StartsWith("NOT "))
            body = body[4..];

        var candidates = new List<(string en, string fr)>();
        // Extension objects: their own conditions/actions from -81 / 80; below, the common ones of all objects
        if (x.ObjectType >= 32 && (kind == "A" ? x.Num >= 80 : x.Num <= -81))
        {
            string file = Out.ExtFile(x.ObjectType);
            string key = $"ext|{file?.ToLowerInvariant()}|{kind}|{x.Num}";
            string t = null;
            if (file != null && !(L.Lang == "fr" && Ext.TryGetValue(key, out t)))
                ExtEn.TryGetValue(key, out t);
            if (t != null)
            {
                string objName = null;
                try { objName = x.GetObjectName(); } catch { }
                // Actions: the object is already in the header ("Ini : "), drop it from the template.
                // Conditions: "<object>: text", as Nebula writes them.
                t = kind == "A" ? Rx.LeadingObject.Replace(t, "")
                    : t.Contains("<object>") || objName == null ? t : "<object>: " + t;
                candidates.Add((null, t));
            }
        }
        else if (L.Lang == "fr" && (Builtin.TryGetValue($"{kind}|{x.ObjectType}|{x.Num}", out var pairs)
                 || x.ObjectType >= 0 && Builtin.TryGetValue($"{kind}|*|{x.Num}", out pairs)))
            candidates.AddRange(pairs);

        // 1. The EN template matches Nebula's text: placeholders take the captured text
        foreach (var (enT, frT) in candidates.Where(p => p.en != null))
        {
            try
            {
                var captured = Capture(x, enT, body);
                if (captured != null)
                    return Finish(Fill(x, enT, frT, captured), prefix, negated);
            }
            catch { }
        }
        // 2. Otherwise, render the placeholders from the parameters (first candidate)
        if (candidates.Count == 0 || x.Parameters.Any(p => p.Code == 72))
            return en;
        try { return Finish(Fill(x, candidates[0].en, candidates[0].fr, null), prefix, negated); }
        catch { return en; }
    }

    static string Finish(string text, string prefix, bool negated) =>
        prefix + (negated ? (L.Lang == "fr" ? "NON " : "NOT ") : "") + (L.Lang == "fr" ? FrenchDirections(text) : text);

    // Direction masks rendered by Nebula ("16 (left)", "all directions"): names in French
    static readonly Dictionary<string, string> DirectionNames = new()
    {
        ["right"] = "droite", ["up-right"] = "haut-droite", ["up"] = "haut", ["up-left"] = "haut-gauche",
        ["left"] = "gauche", ["down-left"] = "bas-gauche", ["down"] = "bas", ["down-right"] = "bas-droite",
    };
    public static string FrenchDirections(string text) =>
        (text.Contains(" (") ? Rx.Direction.Replace(text, m => $"{m.Groups[1].Value} ({DirectionNames[m.Groups[2].Value]})") : text)
             .Replace("all directions", "toutes les directions").Replace("no direction", "aucune direction");

    // Placeholder values of an EN template matched against Nebula's text, or null if it does not match
    static Dictionary<string, string> Capture(ACEventBase x, string enTemplate, string text)
    {
        var names = new List<string>();
        var parts = Rx.PlaceholderSplit.Split(enTemplate);
        var sb = new StringBuilder("^");
        string objName = null;
        foreach (string part in parts)
        {
            if (part.Length > 2 && part[0] == '<' && part[^1] == '>')
            {
                names.Add(part[1..^1]);
                // Known values (object names can contain spaces) keep the match unambiguous
                if (part == "<object>" && (objName ??= x.GetObjectName()) != null)
                    sb.Append($"({Regex.Escape(objName)})");
                else if (part == "<op>")
                    sb.Append("(=|<>|<=|<|>=|>)");
                else
                    sb.Append("(.*?)");
            }
            else
                sb.Append(Regex.Escape(part));
        }
        var m = Regex.Match(text, sb.Append('$').ToString(), RegexOptions.Singleline);
        if (!m.Success)
            return null;
        var values = new Dictionary<string, string>();
        for (int i = 0; i < names.Count; i++)
            values.TryAdd(names[i], m.Groups[i + 1].Value);
        return values;
    }

    // Placeholders rendered in French from the parameters even when captured (the EN text is English)
    static readonly HashSet<string> FrenchRendered = new() { "mouse button", "joystick direction", "player no.", "object" };

    static string Fill(ACEventBase x, string enTemplate, string frTemplate, Dictionary<string, string> captured)
    {
        bool hasOp = frTemplate.Contains("<op>");
        return Rx.Placeholder.Replace(frTemplate, m =>
        {
            string name = m.Groups[1].Value;
            if (captured != null && !FrenchRendered.Contains(name) && captured.TryGetValue(name, out var v))
            {
                // French labels include the operator in the compared parameter: "<op> <p1>" in EN, "<p1>" in FR
                if (!hasOp && captured.TryGetValue("op", out var op) && enTemplate.Contains($"<op> <{name}>"))
                    v = $"{op} {v}";
                return v;
            }
            return Placeholder(x, name, frTemplate, m.Index, hasOp) ?? throw new FormatException(m.Value);
        });
    }

    // Value of one placeholder, or null when it cannot be rendered safely
    static string Placeholder(ACEventBase x, string name, string template, int at, bool hasOp)
    {
        Parameter P(int i) => i < x.Parameters.Length ? x.Parameters[i] : throw new IndexOutOfRangeException();
        var m = Rx.ParamPlaceholder.Match(name);
        if (m.Success)
        {
            int i = int.Parse(m.Groups[2].Value);
            return m.Groups[1].Value switch
            {
                "alterable value" => x.GetObjectAlterableValueName(P(i).Data),
                "alterable string" => x.GetObjectAlterableStringName(P(i).Data),
                "global value" => x.GetGlobalValueName(P(i).Data),
                "global string" => x.GetGlobalStringName(P(i).Data),
                "zone" => x.GetZone(i),
                _ => Param(x, P(i), withOperator: !hasOp),
            };
        }
        switch (name)
        {
            case "object":
                return x.GetObjectName();
            case "op":
                // Operator of the next compared parameter in the template
                var next = Rx.NextParam.Match(template[at..]);
                return next.Success && P(int.Parse(next.Groups[1].Value)).Data is ParameterExpressions pe
                    ? x.GetComparison(pe.Comparison) : null;
            case "player no.":
                return (x.ObjectInfo + 1).ToString();
            case "key":
                return x.GetKeyboardKey(((ParameterShort)P(0).Data).Value);
            case "scene":
                return P(0).Data switch
                {
                    ParameterExpressions e => e.ToString(),
                    ParameterInt v => x.GetFrameName(v.Value),
                    ParameterShort v => x.GetFrameName(v.Value),
                    _ => null
                };
            case "animation":
                return P(0).Data is ParameterShort a ? x.GetObjectAnimation(a.Value) : null;
            case "mouse button":
                return P(0).Data switch
                {
                    ParameterClick c => (c.Button switch { 1 => "du milieu", 2 => "droit", _ => "gauche" })
                                        + (c.IsDouble != 0 ? " (double-clic)" : ""),
                    ParameterShort s => s.Value switch { 2 => "droit", 4 => "du milieu", _ => "gauche" },
                    _ => null
                };
            case "joystick direction":
                return P(0).Data is ParameterShort j ? Joystick(j.Value) : null;
            default:
                return null; // <value>, <direction>, <menu option>... : keep English
        }
    }

    // Joystick test (bits: up, down, left, right, fire 1-4), like ACEventBase.GetJoystickString
    static string Joystick(short flags)
    {
        bool B(int bit) => (flags & (1 << bit)) != 0;
        var parts = new List<string>();
        var fires = Enumerable.Range(1, 4).Where(i => B(3 + i)).Select(i => $"feu {i}").ToList();
        if (fires.Count > 0)
            parts.Add("appuie sur " + string.Join("+", fires));
        string v = B(0) ? "en haut" : B(1) ? "en bas" : null;
        string h = B(2) ? "à gauche" : B(3) ? "à droite" : null;
        string move = v != null && h != null ? $"{v} {h}" : v ?? h;
        if (move != null)
            parts.Add("déplacé " + move);
        return parts.Count > 0 ? string.Join(", ", parts) : null;
    }

    // One parameter: names of values/strings, and the comparison operator in front of a compared
    // value when the template has no <op> (French editor labels include it in the parameter)
    static string Param(ACEventBase x, Parameter p, bool withOperator)
    {
        string text = p.Code switch
        {
            50 => x.GetObjectAlterableValueName(p.Data),
            61 => x.GetObjectAlterableStringName(p.Data),
            49 => x.GetGlobalValueName(p.Data),
            58 => x.GetGlobalStringName(p.Data),
            _ => p.ToString()
        };
        if (withOperator && Array.IndexOf(ComparisonCodes, p.Code) >= 0 && p.Data is ParameterExpressions e)
            text = $"{x.GetComparison(e.Comparison)} {text}";
        return text;
    }
}

static class Out
{
    public static StreamWriter Jsonl;
    // Extension index -> (displayed name, .mfx file without extension)
    public static Dictionary<int, (string name, string file)> Extensions = new();
    public static string Frame = "";
    static readonly JsonSerializerOptions JsonOpts = new() { Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping };

    public static string ExtFile(int type) => ExtOf(type).Item2;

    // One line per condition/action ("C"/"A"), then one per item of the expressions of its parameters ("E")
    public static void Record(string kind, int ev, ACEventBase x, string text)
    {
        if (Jsonl == null)
            return;
        string obj = null;
        if (x.ObjectType >= 0)
            try { obj = x.GetObjectName(); } catch { }
        var (ext, extFile) = ExtOf(x.ObjectType);
        Write(new
        {
            frame = Frame, ev, kind, type = x.ObjectType, num = x.Num, ext, extFile, obj,
            neg = x is Condition c && c.OtherFlags["Negated"],
            pars = x.Parameters.Select(p => p.Code).ToArray(),
            text
        });
        foreach (var exprs in x.Parameters.Select(p => p.Data).OfType<ParameterExpressions>())
            foreach (var e in exprs.Expressions)
            {
                var (eExt, eFile) = ExtOf(e.ObjectType);
                string eText;
                try { eText = e.ToString(); } catch (Exception ex) { eText = $"[?? {ex.GetType().Name}]"; }
                Write(new { frame = Frame, ev, kind = "E", type = e.ObjectType, num = e.Num, ext = eExt, extFile = eFile, text = eText });
            }
    }

    static (string, string) ExtOf(int type) =>
        type >= 32 && Extensions.TryGetValue(type - 32, out var e) ? e : (null, null);

    static void Write(object o) => Jsonl.WriteLine(JsonSerializer.Serialize(o, JsonOpts));
}

// Fixed regular expressions, built once (the static Regex methods keep only 15 patterns in their cache,
// shared with the per-template patterns of Tr.Capture)
static class Rx
{
    public static readonly Regex ValueOfObject = new(@"Alterable Value ([A-Z]{1,2})\(""([^""]+)""\)");
    public static readonly Regex StringOfObject = new(@"Alterable String ([A-Z]{1,2})\(""([^""]+)""\)");
    public static readonly Regex OwnString = new(@"Alterable String ([A-Z]{1,2})(?![A-Z(])");
    public static readonly Regex OwnValue = new(@"Alterable Value ([A-Z])(?![A-Z(])");
    public static readonly Regex Flag = new(@"(Flag|drapeau) (\d+)(?! «)");
    public static readonly Regex OfHost = new(@"Alterable (Value|String) ([A-Z]{1,2}) of (.+?)(?= (?:<>|=|<|>|!=|<=|>=)|[,)]|$)");
    public static readonly Regex HostValue = new(@"Alterable (Value|String) ([A-Z]{1,2})(?![A-Z(\w])");
    public static readonly Regex Player = new(@"^Player (\d+) : $");
    public static readonly Regex LeadingObject = new(@"^<object>\s*:?\s*");
    public static readonly Regex Direction = new(@"\b(\d+) \((right|up-right|up|up-left|left|down-left|down|down-right)\)");
    public static readonly Regex PlaceholderSplit = new(@"(<[^<>]+>)");
    public static readonly Regex Placeholder = new(@"<([^<>]+)>");
    public static readonly Regex ParamPlaceholder = new(@"^(?:(alterable value|alterable string|global value|global string|zone) )?p(\d+)$");
    public static readonly Regex NextParam = new(@"p(\d+)>");
}

